solution:
for (let i = 0; i < 4; i++) {
  let row = '';
  for (let j = 0; j < 6; j++) {
    if (i === 0 || i === 3 || j === 0 || j === 5) {
      row += '#';
    } else {
      row += ' ';
    }
  }
  console.log(row);
}
